"""The Pallet crushed house keeper (data/scenes.json pallet_crushed_house keepers, generated by tools/scenes_pack.py).

Written in the same session that wrote the keeper (the owner asked for it in the brief): an independent audit is still owed.
The keeper's function is read back as GENERATED and run by tests/keeper_sim.py, not recomputed from the data, and the
mutations that were run against the generator (not the data) are named in each test.

What is asserted: the selection (one finished and one unfinished player in the area gives inside, all finished gives
outside, nobody in the area gives no move at all), the hold (no move while a conversation holds it), that only the one
existing Lena is ever moved (found by tag at her own stands, never summoned, Hank untouched), and that a stale position
is corrected without a second one. NOT covered, needs a running server: that Minecraft accepts each selector, that
`@s[x=,y=,z=,distance=]` measures from those coordinates, that Cobblemon keeps or drops a dialogue screen when its NPC is
teleported, and that the beat's tag commands land before the keeper reads them in the same cycle.
"""
import json
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tools"))
sys.path.insert(0, str(ROOT / "tests"))

import keeper_sim as KS  # noqa: E402
import molang_dialogue_sim as SIM  # noqa: E402
import scenes_pack as SP  # noqa: E402

DATA = ROOT / "data"
SEATS = json.loads((DATA / "npc_seats.json").read_text(encoding="utf-8"))
IN = SEATS["markers"]["marker_pallet_crushed_house_interior_safe"]
OUT = SEATS["markers"]["marker_pallet_crushed_house_exterior_safe"]
HANK = next(s for s in SEATS["seats"] if s["id"] == "npc_pallet_crushed_house_hank")
KEEP = "data/cobblers/function/scenes/pallet_crushed_house/keep_lena.mcfunction"
RESCUED, HOLD, OBJ = "cobblers_pallet_rescued", "cobblers_hold", "cobblers_scene"
LENA_TAG = "cobblers_actor_npc_pallet_crushed_house_lena"
FILES, SCENES = SP.build(DATA)
INSIDE, OUTSIDE = (IN["at"][0] + .5, IN["at"][1], IN["at"][2] + .5), (OUT["at"][0] + .5, OUT["at"][1], OUT["at"][2] + .5)
NEAR = (1510.5, 118.0, 5254.5)       # inside the scene's area
FAR = (1462.5, 118.0, 5300.0)        # the main street, outside it


class Setup:
    def __init__(self, lena_at, files=FILES):
        self.w = SIM.World()
        self.w.pos = {}
        self.lena = SIM.Npc("lena", 0, 0, 0)
        self.lena.pos = lena_at
        self.hank = SIM.Npc("hank", *HANK["at"])
        self.w.npcs += [self.lena, self.hank]
        self.k = KS.Keeper(self.w, files[KEEP])

    def player(self, name, finished, where=NEAR, hold=0):
        p = self.w.player(name)
        if finished:
            p.tags.add(RESCUED)
        if hold:
            p.scores[HOLD] = hold
        self.w.pos[name] = where
        return p

    def cycle(self):
        self.k.cycle()
        return "in" if self.lena.pos == INSIDE else "out" if self.lena.pos == OUTSIDE else self.lena.pos


@pytest.mark.parametrize("start", [INSIDE, OUTSIDE])
def test_one_finished_and_one_unfinished_player_in_the_area_put_her_inside(start):
    # Without it the first finisher (or anyone who has finished) takes her away from a player who has not: the owner's bug.
    # Mutated in the generator: `tag=!done` written as `tag=done` fails this.
    s = Setup(start)
    s.player("done", True)
    s.player("new", False)
    assert s.cycle() == "in"
    assert s.w.scores[("#evt_pallet_crushed_house.house_state", "cobblers_world")] == 0


@pytest.mark.parametrize("start", [INSIDE, OUTSIDE])
def test_every_player_in_the_area_finished_puts_her_outside(start):
    # Without it she stays in the pocket for ever after the last player has finished.
    s = Setup(start)
    s.player("a", True)
    s.player("b", True)
    assert s.cycle() == "out"
    assert s.w.scores[("#evt_pallet_crushed_house.house_state", "cobblers_world")] == 1


def test_an_unfinished_player_outside_the_area_does_not_count():
    # Without it a friend on the far side of the map keeps her inside for the player who is standing beside her.
    s = Setup(INSIDE)
    s.player("here", True)
    s.player("away", False, where=FAR)
    assert s.cycle() == "out"


def test_nobody_in_the_area_moves_nothing_and_writes_no_state():
    # Without it she is teleported in an empty town (and her chunk may not even be loaded). Mutating the generator to drop
    # the `near` clause from the move commands fails this.
    for start in (INSIDE, OUTSIDE):
        s = Setup(start)
        s.player("away", False, where=FAR)
        s.w.player("offline")                           # known to the world but with no position: not online
        before = s.lena.pos
        assert s.cycle() is not None and s.lena.pos == before
        assert not s.w.scores.get(("#evt_pallet_crushed_house.house_state", "cobblers_world"))
        assert not any(c.startswith("tp ") for c in s.k.log)


def test_a_player_holding_her_conversation_keeps_her_where_she_is_until_it_runs_out():
    # Without it she is teleported from under a player mid-line. The hold is a proxy: the NPC offers no documented
    # 'in a dialogue' read. Mutating the generator to drop the `busy` clause fails this.
    s = Setup(OUTSIDE)
    s.player("talker", True, hold=3)
    s.player("new", False)
    assert [s.cycle() for _ in range(3)] == ["out"] * 3
    assert s.w.player("talker").scores[HOLD] == 0
    assert s.cycle() == "in"


def test_only_the_one_existing_lena_is_ever_moved_and_nothing_is_summoned():
    # Without it the keeper adds a second Lena (the apply's near-stand check cannot see her) or drags Hank about.
    s = Setup(OUTSIDE)
    s.player("new", False)
    s.cycle()
    assert len(s.w.npcs) == 2 and s.hank.pos == (HANK["at"][0] + .5, HANK["at"][1], HANK["at"][2] + .5)
    assert s.hank.tags == set() and s.lena.tags == {LENA_TAG}
    text = "\n".join(FILES[KEEP])
    assert "summon" not in text and "spawnnpcat" not in text and "kill" not in text


def test_a_lena_that_stands_at_neither_marker_is_left_alone_not_duplicated():
    # Without it the keeper tags whatever NPC is near (Hank) or invents a stand for a Lena somebody moved by hand.
    s = Setup((1500.5, 118.0, 5250.5))
    s.player("new", False)
    assert s.cycle() == s.lena.pos == (1500.5, 118.0, 5250.5) and s.lena.tags == set()


def test_a_second_cycle_changes_nothing_once_she_is_where_the_players_need_her():
    # Without it she is teleported every second (her animation and her dialogue restart with each teleport).
    s = Setup(OUTSIDE)
    s.player("new", False)
    s.cycle()
    s.k.log.clear()
    s.cycle()
    assert not any(c.startswith("tp ") for c in s.k.log)


def test_the_hold_functions_set_the_objective_the_keeper_reads():
    # Without it the dialogue holds one objective and the keeper reads another, and nothing ever holds her.
    for fn, n in (("lena_talk", 40), ("lena_release", 0)):
        lines = [x for x in FILES["data/cobblers/function/scenes/pallet_crushed_house/fn/%s.mcfunction" % fn] if not x.startswith("#")]
        assert lines == ["scoreboard players set @s %s %d" % (HOLD, n)]
    assert ("scoreboard objectives add %s dummy" % HOLD) in FILES["data/cobblers/function/scenes/load.mcfunction"]
    assert "function cobblers:scenes/pallet_crushed_house/keep_lena" in FILES["data/cobblers/function/scenes/cycle.mcfunction"]


def test_the_scene_area_holds_both_stands_and_hank_and_the_lot():
    # Without it a player at the opening is outside the area (she would never be moved for them).
    scene = next(s for s in json.loads((DATA / "scenes.json").read_text(encoding="utf-8"))["scenes"] if s["id"] == "pallet_crushed_house")
    lo, hi = scene["area"]["from"], scene["area"]["to"]
    for p in (IN["at"], OUT["at"], HANK["at"], [1512, 118, 5254], [1520, 118, 5262]):
        assert all(lo[i] <= p[i] <= hi[i] for i in range(3)), p


def test_a_keeper_that_names_a_marker_the_seats_do_not_have_is_refused(tmp_path):
    # Without it a typo leaves a keeper that moves her to nowhere. Run against a copy of the real data.
    import shutil
    for f in DATA.glob("*.json"):
        shutil.copy(f, tmp_path / f.name)
    doc = json.loads((tmp_path / "scenes.json").read_text(encoding="utf-8"))
    next(s for s in doc["scenes"] if s["id"] == "pallet_crushed_house")["keepers"][0]["outside_marker"] = "marker_nowhere"
    (tmp_path / "scenes.json").write_text(json.dumps(doc), encoding="utf-8")
    with pytest.raises(SP.SceneError, match="marker_nowhere"):
        SP.build(tmp_path)
